def numberOfSubstrings(s: str) -> int:
    last_seen = {'a': -1, 'b': -1, 'c': -1}
    count = 0

    for i, ch in enumerate(s):
        last_seen[ch] = i
        # If all three have been seen at least once
        if all(v != -1 for v in last_seen.values()):
            count += 1 + min(last_seen.values())

    return count
